    def test_net_zero(self):
        assert due_date("2024-01-15", 0) == "2024-01-15"

    def test_lands_on_saturday(self):
        # 2024-01-13 is a Saturday
        assert due_date("2024-01-13", 0) == "2024-01-15"

    def test_lands_on_sunday(self):
        # 2024-01-14 is a Sunday
        assert due_date("2024-01-14", 0) == "2024-01-15"

    def test_saturday_via_net_days(self):
        # 2024-01-01 + 6 days = 2024-01-07 (Sunday) -> Monday 2024-01-08
        assert due_date("2024-01-01", 6) == "2024-01-08"

    def test_sunday_via_net_days(self):
        # 2024-01-01 + 5 days = 2024-01-06 (Saturday) -> Monday 2024-01-08
        assert due_date("2024-01-01", 5) == "2024-01-08"

    def test_friday_stays_friday(self):
        # 2024-01-12 is a Friday
        assert due_date("2024-01-12", 0) == "2024-01-12"

    def test_monday_stays_monday(self):
        # 2024-01-15 is a Monday
        assert due_date("2024-01-15", 0) == "2024-01-15"

