from typing import Optional, Sequence, Tuple
from src.ledgerlib.round_div import round_div

def tiered_fee(volume_cents: int, tiers: Sequence[Tuple[Optional[int], int]], min_fee_cents: int = 0) -> int:
    if volume_cents < 0: raise ValueError("negative volume")
    if not tiers: raise ValueError("empty tiers")
    if tiers[-1][0] is not None: raise ValueError("last bound must be None")

    total_bp = 0
    prev_bound = 0
    for bound, rate in tiers:
        current_bound = bound if bound is not None else float('inf')
        if current_bound <= prev_bound and bound is not None: 
            raise ValueError("invalid bounds")

        tier_vol = max(0, min(volume_cents, int(current_bound)) - prev_bound)
        total_bp += tier_vol * rate
        prev_bound = int(current_bound) if bound is not None else volume_cents

    fee = round_div(total_bp, 10000, mode="half_up")
    return max(fee, min_fee_cents)"
    }
  },
